<?php
 require_once(__DIR__ . '/../init.php'); class reportbuilder_param { const TASK_NAME = 'report'; const DEBUG_HTTP = true; const FTYPES = [ 'ptNone_notUsed', 'ptDate', 'ptTime', 'ptField', 'ptText', 'ptMark', 'ptMonth', 'ptYear', 'ptStringField', 'ptDateField', 'pt_String_notUsed', 'pt_Integer_notUsed', 'pt_Float_notUsed', 'pt_DateTime_notUsed', 'ptFont_notUsed' ]; private $db; private $type; private $report; private $user; private $designer; private $reportCode; private function setupParams($params) { if (!$this->db) { $this->db = connectDb(); $exdata = getSessionValue('exdata', []); $this->user = getSessionValue('user'); $this->type = isNullArrayValue($exdata, 'type', isNullProperty($params, 'type', 0)); $this->report = isNullArrayValue($exdata, 'report', isNullProperty($params, 'report')); if (!($this->designer = isNullArrayValue($exdata, 'designer', false))) { checkUserAccess("report-{$this->type}-{$this->report}", $this->db); } } } public function readParams($params) { $this->setupParams($params); if ($this->type === 0) { $ret = self::loadStimulsoftReportData($this->report); if (!empty($ret->data)) { $userParameters = self::loadStimulsoftUserParameters($this->db, $this->user, $this->report); $ret->items = self::loadStimulsoftParamItems($this->db, $this->user, $this->report, $ret->data, $userParameters, true); unset($ret->data); } } else { $ret = $this->loadMapReportData(); $ret->items = $this->loadMapParamItems($params, $ret->reportListCode); } if ($this->designer) { $ret->designer = true; } return $ret; } private static function extractScriptParams ($script) { $params = []; $lexem = null; preg_replace_callback('#(\'|--|/\*|\*/|\n|(?<!:):[A-ZА-Я0-9_]+)#iu', function ($matches) use (&$params, &$lexem) { $m = $matches[0]; if ($lexem) { if (($lexem === "'" && $m === "'") || ($lexem === '/*' && $m === '*/') || ($lexem === '--' && $m === "\n")) $lexem = null; } else if (mb_substr($m, 0, 1) !== ':') { if ($m !== "\n") $lexem = $m; } else { $params[] = mb_strtolower($m); } return $m; }, $script); return empty($params) ? null : array_values(array_unique($params)); } private function loadMapParamItems ($params, $reportListCode) { $db = $this->db; $userCode = getSessionValue('mapUserCode', 0); $setCode = isUndefinedProperty($params, 'setCode', null); $isSetCode = $setCode ? 1 : 0; $sql = <<<"EOT"
select
    p.ReportInCode "reportInCode",
    p.Position "position",
    sn.SysNumberCode "subPosition",
    d.ReportUserDataCode "reportUserDataCode",
    p.Name || case
        when p.TypeIn between 6 and 7 then
