    /*p.Name "originalName",*/
    p.TypeIn "typeIn",
    p.MultiSelect "multiSelect",
    p.DefaultValue "defaultValue",
    case when p.TypeIn in (3,8,9) then 1 else
        case when p.TypeIn between 10 and 13 then 0 else p.ValueSave end
        end "valueSave",
    p.SelectListCode "selectListCode",
    case when sn.SysNumberCode = 1 or p.TypeIn in (8,9,14) or (p.TypeIn = 3 and coalesce(p.DefaultValue, 0) <> (4))
        then
            p.ResultVisibility
        else
