EOT;
$stmt = $db->prepare($sql); $stmt->execute([$isSetCode, $setCode, $isSetCode, $userCode, $reportListCode]); $ret = $stmt->fetchAll(); foreach ($ret as &$row) { if ($row['script']) { $row['scriptParams'] = self::extractScriptParams($row['script']); } unset($row['script']); } return $ret; } static public function loadStimulsoftParamItems ($db, $user, $report, $reportData, $userParameters, $isFront) { $toTypeIn = function ($type, $dateTimeType, &$isRange) { $isRange = false; if (preg_match('/\.DateTime($|\W)/u', $type)) return ($dateTimeType === 'Date') ? 1 : 2; if (preg_match('/\.Boolean($|\W)/u', $type)) return 5; if (preg_match('/\.IntList($|\W)/u', $type)) return 3; if (preg_match('/\.StringList($|\W)/u', $type)) return 8; if (preg_match('/\.DateTimeList($|\W)/u', $type)) return 9; if (preg_match('/\.DateTimeRange($|\W)/u', $type)) { $isRange = true; return 1; } return 4; }; $findScriptParams = function ($dictionary, $var) { if(!empty($dictionary->DataSources) && !empty($var->DialogInfo->KeysColumn)) { $dsName = preg_replace('/\..*/u', '', $var->DialogInfo->KeysColumn); foreach ($dictionary->DataSources as $ds) { if ($ds->Name === $dsName) { if (!empty($ds->SqlCommand)) { return self::extractScriptParams($ds->SqlCommand); } break; } } } return null; }; $ret = []; if (empty($dictionary = isUndefinedProperty($reportData, 'Dictionary')) || empty($variables = isUndefinedProperty($dictionary, 'Variables'))) { return $ret; } $userVariables = $userParameters->variables; $usedVariables = new stdClass(); $position = 0; foreach ($variables as $reportInCode => $var) { $dialogInfo = isEmptyProperty($var, 'DialogInfo', new stdClass()); $dateTimeType = isEmptyProperty($dialogInfo, 'DateTimeType', 'Date'); $allowUserValues = isUndefinedProperty($dialogInfo, 'AllowUserValues', true); $isExpression = isUndefinedProperty($var, 'InitBy') === 'Expression'; $typeIn = $toTypeIn($var->Type, $dateTimeType, $isRange); $description = mb_strtoupper(isEmptyProperty($var, 'Description', '')); $multiSelect = $isRange || ($typeIn === 2 && $dateTimeType === 'Time') || (($typeIn === 3 || $typeIn === 8 || $typeIn === 9) && $allowUserValues); $selectAll = (($typeIn === 3 || $typeIn === 8 || $typeIn === 9) && $allowUserValues) ? 1 : 0; if ($description) { if (mb_strpos($description, 'HIDDEN()') !== false) { continue; } if ($selectAll && mb_strpos($description, 'NOTALL()') !== false) { $selectAll = 0; } if (($typeIn === 1 || $typeIn === 2)) { if (mb_strpos($description, 'MONTH()') !== false) { $typeIn = 6; } else if (mb_strpos($description, 'YEAR()') !== false) { $typeIn = 7; } } } if (($typeIn === 1 || $typeIn === 2) && $isExpression) { if (mb_strtoupper($var->Value) === 'MONTH()') { $typeIn = 6; } else if (mb_strtoupper($var->Value) === 'YEAR()') { $typeIn = 7; } } $valueSave = ($typeIn === 3 || $typeIn === 8 || $typeIn === 9) || $allowUserValues; $defaultValue = null; $valueText = null; if ($typeIn === 5) { $defaultValue = 3; $valueText = (isset($var->Value) && $var->Value === 'true') ? '1' : '0'; } else if (isset($var->Value) && !$isRange && !$isExpression) { $defaultValue = 3; if ($typeIn === 1) { $valueText = safe_date_create($var->Value)->format('d.m.Y'); } else if ($typeIn === 2) { $valueText = safe_date_create($var->Value)->format('H:i:s'); } else { $valueText = $var->Value; } } else if ($typeIn === 1 || $typeIn === 2) { $defaultValue = $typeIn; } if ($isFront) { $scriptParams = $fieldValueName = $fieldValueResultName = $selectListCode = null; if ($typeIn === 3 || $typeIn === 8 || $typeIn === 9) { $scriptParams = $findScriptParams($dictionary, $var); $fieldValueName = preg_replace('/.*\./u', '', isUndefinedProperty($dialogInfo, 'ValuesColumn', 'name')); $fieldValueResultName = preg_replace('/.*\./u', '', isUndefinedProperty($dialogInfo, 'KeysColumn', 'id')); $selectListCode = (int)$reportInCode; } } $reportUserDataCode = $lastValue = $lastValueResult = null; if (!empty($dbVar = isUndefinedProperty($userVariables, $var->Name)) && is_object($dbVar)) { $lastValue = isUndefinedProperty($dbVar, 'value'); $lastValueResult = isUndefinedProperty($dbVar, 'displayValue'); $usedVariables->{$var->Name} = (object)[ 'value' => $lastValue, 'displayValue' => $lastValueResult ]; if($valueSave) { $reportUserDataCode = (int)$reportInCode; } } ++$position; for ($subPosition = 1; $subPosition <= 2; $subPosition++) { if ($subPosition === 2 && !($typeIn === 6 || $typeIn === 7 || (($typeIn === 3 || $typeIn === 8 || $typeIn === 9) && $allowUserValues && $selectAll))) { continue; } $name = $var->Name; if ($typeIn === 6 || $typeIn === 7) { $name .= $subPosition === 1 ? '_Начало_' : '_Конец_'; } else if (($typeIn === 3 || $typeIn === 8 || $typeIn === 9) && $subPosition === 2) { $name .= '_Все'; } if ($isFront) { $item = [ 'reportInCode' => (int)$reportInCode, 'position' => $position, 'subPosition' => $subPosition, 'reportUserDataCode' => $reportUserDataCode, 'name' => $name, 'typeIn' => $typeIn, 'multiSelect' => (int)$multiSelect, 'selectAll' => $selectAll, 'defaultValue' => $defaultValue, 'valueSave' => (int)$valueSave, 'resultVisibility' => 1, 'valueChecked' => 1, 'valueUnchecked' => 0, 'valueText' => $valueText, 'label' => $var->Alias ?? $var->Name, 'lastValue' => $lastValue, 'lastValueResult' => $lastValueResult, 'scriptParams' => $scriptParams, 'fieldValueName' => $fieldValueName, 'fieldValueResultName' => $fieldValueResultName, 'selectListCode' => $selectListCode ]; } else { $item = [ 'sub' => $subPosition, 'name' => $name, 'type' => $typeIn, 'multi' => (int)$multiSelect, 'all' => $selectAll, 'value' => isset($lastValue) ? $lastValue : $valueText, 'result' => (string)$lastValueResult != '' ? $lastValueResult : $lastValue ]; } $ret[] = $item; } } if ($isFront && count(get_object_vars($usedVariables)) !== count(get_object_vars($userVariables))) { $userParameters->variables = $usedVariables; self::saveStimulsoftUserParameters($db, $user, $report, $userParameters); } return $ret; } public static function cleanNonprintableChars($value) { if (is_string($value)) { return preg_replace('/[\x{200B}-\x{200D}\x{FEFF}]/u', '', $value); } return $value; } public function updateParams($params) { $this->setupParams($params); $db = $this->db; $ret = []; if (empty($params->params)) return $ret; if ($this->type === 0) { $userParameters = self::loadStimulsoftUserParameters($db, $this->user, $this->report); $userVariables = $userParameters->variables; foreach ($params->params as $param) { $isNew = (empty($dbVar = isUndefinedProperty($userVariables, $param->name)) || !is_object($dbVar)); $dbVar = $isNew ? new stdClass() : $dbVar; $dbVar->value = isUndefinedProperty($param, 'lastValue'); $dbVar->displayValue = isUndefinedProperty($param, 'lastValueResult'); $userVariables->{$param->name} = $dbVar; if ($isNew) { $ret[] = (object)[ 'key' => $param->key, 'id' => $param->key ]; } } $userParameters->variables = $userVariables; self::saveStimulsoftUserParameters($db, $this->user, $this->report, $userParameters); } else { $sqlUpdate = <<<"EOT"
