EOT;
$stmtInsert = $db->prepare($sqlInsert); $db->beginTransaction(); try { $userCode = getSessionValue('mapUserCode'); foreach ($params->params as $param) { if ($param->reportUserDataCode) { $stmtUpdate->execute([ reportbuilder_param::cleanNonprintableChars(isNullProperty($param, 'lastValue', '')), reportbuilder_param::cleanNonprintableChars(isNullProperty($param, 'lastValueResult', '')), $param->reportUserDataCode ]); } else { $setCode = isUndefinedProperty($param, 'setCode', null); $stmtInsert->execute([ $param->reportInCode, reportbuilder_param::cleanNonprintableChars(isNullProperty($param, 'lastValue', '')), reportbuilder_param::cleanNonprintableChars(isNullProperty($param, 'lastValueResult', '')), $setCode ? null : $userCode, $setCode ]); $rec = new stdClass; $rec->key = $param->key; $rec->id = $db->lastInsertId('seq_ReportUserData'); $ret[] = $rec; } } $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } } return $ret; } private function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } public function readParamsSelect($params) { $this->setupParams($params); $db = $this->db; $script = ''; if ($this->type === 0) { $data = self::loadStimulsoftReportData($this->report)->data; if (!empty($dictionary = isUndefinedProperty($data, 'Dictionary')) && !empty($variables = isUndefinedProperty($dictionary, 'Variables')) && !empty($var = isUndefinedProperty($variables, (string)$params->code)) && !empty($dialogInfo = isUndefinedProperty($var, 'DialogInfo'))) { if (!empty($dialogInfo->KeysColumn)) { $dsName = preg_replace('/\..*/u', '', $dialogInfo->KeysColumn); foreach ($dictionary->DataSources as $ds) { if ($ds->Name === $dsName) { if (!empty($ds->SqlCommand)) { $script = $ds->SqlCommand; } break; } } } if (empty($script) && !empty($dialogInfo->Keys) && !empty($dialogInfo->Values)) { foreach ($dialogInfo->Keys as $i => $k) { $script .= ($script ? ',' : '') . "('$k','{$dialogInfo->Values->{$i}}')"; } $script = "SELECT * FROM (VALUES $script)