: $value = $value ? ("'" . dbDate($value). "'::date") : "'0001-01-01'::date"; break; } } if ($sub == 1 && ($value === null || $value === '' || $value === '()') && ($type == 3 || $type == 8 || $type == 9)) { $errorParams .= "<li>$param->label</li>"; return $m; } if ($several && $sub === 1) { return (is_string($value) && mb_strpos($value, ',') !== false) ? 1 : 0; } return $value; } $errorParams .= "<li>$param->label</li>"; return $m; }, $script); if (!empty($errorParams)) { return ['errorParams' => "Для выбора <b>$params->name</b> заполните обязательные параметры:<ul>$errorParams</ul>"]; } $script = rtrim($script, "; \n\r\t"); $fldName = $params->fieldValueName; $fldCode = $params->fieldValueResultName; $isPaging = isset($params->page); $isFirst = !isset($params->total); $search = isNullProperty($params, 'search', ''); $method = isNullProperty($params, 'method', 1); if ($search) { if ($method == 2) { $like = "%$search%"; } else if ($method == 3) { $like = "$search"; } else { $like = "$search%"; } $script = "select * from ($script) as t where t.$fldName ilike '$like'"; } if ($search != isNullProperty($params, 'oldSearch', '') || $method != isNullProperty($params, 'oldMethod', 1)) { $isFirst = true; } $countScript = $script; if ($isPaging) { $maxRecords = $isFirst ? $params->limit + 1 : $params->limit; if (!empty($db->isSybase)) { $posSelect = stripos($script, 'select'); if ($posSelect !== false) { $start = $params->start + 1; $script = "SELECT TOP $maxRecords START AT $start " . substr($script, $posSelect + 6); } } else { $script .= " LIMIT $maxRecords OFFSET $params->start"; } } $stmtSelect = $db->prepare($script); $stmtSelect->execute(); $ret = []; $items = []; while ($row = $stmtSelect->fetch()) { $items[] = [ 'field1' => $row[$fldCode] ?? $row[mb_strtolower($fldCode)], 'field2' => $row[$fldName] ?? $row[mb_strtolower($fldName)] ]; } $ret['items'] = $items; $ret['total'] = count($items); if ($isPaging) { if ($isFirst) { if ($ret['total'] > $params->limit) { array_pop($ret['items']); $ret['total'] = (int) selectSqlValue($db, "select count(*) from ($countScript) as t", null); } } else { $ret['total'] = $params->total; } } return $ret; } public function getRemotelyReport($params) { $userCode = getSessionValue('mapUserCode'); $appConfig = getSessionValue('appConfig'); $format = isUndefinedProperty($params, 'format', 'pdf'); $format = $format == "odf" ? "ods" : $format; $currentTask = getSessionValue('mapWebTaskCode', 57); $sendParams = new stdClass(); $sendParams->args = new stdClass(); $sendParams->args->reportListCode = $params->reportListCode; $sendParams->args->taskType = $params->taskType; $sendParams->args->reportLabel = $params->reportLabel; $sendParams->args->userCode = $userCode; $sendParams->args->dbAlias = property_exists($params, 'dbAlias') ? $params->dbAlias : null; $sendParams->args->silent = property_exists($params, 'silent') ? $params->silent : null; $sendParams->method = 'startRemotelyReport'; $sendParams->url = $appConfig['remoteReport']['host'] . '/service/map/reports/params.php'; $sendParams->proxy = null; $sendParams->timeout = isset($params->timeout) && isEmptyProperty($params, 'timeout') ? $params->timeout : 30 * 60 * 1000; $sendParams->debug = isset($params->debug) && isEmptyProperty($params, 'debug') ? $params->debug : false; $sendParams->args->reportName = isUndefinedProperty($params, 'reportName', null); $sendParams->args->splitPages = isUndefinedProperty($params, 'splitPages', null) ? "True" : "False"; $sendParams->args->layoutDetails = isUndefinedProperty($params, 'layoutDetails', null); $sendParams->args->format = $format; $sendParams->args->currentTask = $currentTask; $result = httpJsonRpc($sendParams); if (property_exists($result, 'error')) { throw new \Exception($result->error->message); } if (!is_object($result)) { $result = safe_json_decode($result ?? ''); } if (!empty($result->result->reportFile)) { $reportFile = base64_decode($result->result->reportFile); $fp = fopen(realpath(sys_get_temp_dir()